<?php
require_once __DIR__ . '/app.php'; require_login(); $me=current_user(); $q=trim((string)($_GET['q']??''));
if ($q !== '') { $like='%'.$q.'%'; $stmt=$conn->prepare('SELECT u.id,u.username,u.display_name,u.avatar_path,u.bio,(SELECT COUNT(*) FROM follows f WHERE f.followed_id=u.id) followers, EXISTS(SELECT 1 FROM follows f2 WHERE f2.follower_id=? AND f2.followed_id=u.id) is_following FROM users u WHERE u.id<>? AND (u.username LIKE ? OR u.display_name LIKE ? OR u.bio LIKE ?) ORDER BY followers DESC,u.username LIMIT 100'); $stmt->bind_param('iisss',$me['id'],$me['id'],$like,$like,$like); }
else { $stmt=$conn->prepare('SELECT u.id,u.username,u.display_name,u.avatar_path,u.bio,(SELECT COUNT(*) FROM follows f WHERE f.followed_id=u.id) followers, EXISTS(SELECT 1 FROM follows f2 WHERE f2.follower_id=? AND f2.followed_id=u.id) is_following FROM users u WHERE u.id<>? ORDER BY followers DESC,u.created_at DESC LIMIT 100'); $stmt->bind_param('ii',$me['id'],$me['id']); }
$stmt->execute(); $people=$stmt->get_result(); page_start('Explore','explore');
?>
<main class="content-wrap"><div class="section-heading explore-heading"><div><span class="eyebrow muted">MEET YOUR NEXT FOLLOW</span><h1>Explore<span class="heading-dot">.</span></h1><p class="muted">Discover people, ideas, and corners of the community you haven’t met yet.</p></div></div><form class="search-large" method="get"><span>⌕</span><input name="q" type="search" placeholder="Search names, usernames, or interests…" value="<?= e($q) ?>"><button class="btn primary" type="submit">Search</button><?php if($q!==''): ?><a class="clear-search" href="explore.php">Clear</a><?php endif; ?></form><?php if($people->num_rows===0): ?><div class="empty-state card"><div class="empty-icon">⌕</div><h2>No matches just yet.</h2><p>Try a different name or search term.</p></div><?php else: ?><div class="people-grid"><?php while($person=$people->fetch_assoc()): ?><article class="person-card card"><a class="person-avatar-wrap" href="profile.php?u=<?= urlencode($person['username']) ?>"><img class="person-avatar" src="<?= e(avatar(['avatar_path'=>$person['avatar_path']])) ?>" alt=""></a><h3><?= e($person['display_name']) ?></h3><p class="handle">@<?= e($person['username']) ?></p><p class="person-bio"><?= e($person['bio'] ?: 'Finding their rhythm on Social Pulse.') ?></p><div class="person-meta"><span><strong><?= (int)$person['followers'] ?></strong> followers</span></div><?php if($person['is_following']): ?><form method="post" action="follow.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$person['id'] ?>"><input type="hidden" name="mode" value="unfollow"><button class="btn secondary full" type="submit">Following ✓</button></form><?php else: ?><form method="post" action="follow.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$person['id'] ?>"><input type="hidden" name="mode" value="follow"><button class="btn primary full" type="submit">＋ Follow</button></form><?php endif; ?></article><?php endwhile; ?></div><?php endif; ?></main>
<?php page_end(); ?>
